function getRelativeTime(timestamp2) {
  const now4 = Date.now();
  const diff = now4 - timestamp2;
  const seconds2 = Math.floor(diff / 1000);
  const minutes2 = Math.floor(seconds2 / 60);
  const hours2 = Math.floor(minutes2 / 60);
  const days2 = Math.floor(hours2 / 24);
  if (seconds2 < 60)
    return "just now";
  if (minutes2 < 60)
    return `${minutes2}m ago`;
  if (hours2 < 24)
    return `${hours2}h ago`;
  if (days2 < 7)
    return `${days2}d ago`;
  return Locale.datetime(timestamp2);
}
