function getNetworkIPs() {
  const nets = networkInterfaces();
  const results = [];
  for (const name26 of Object.keys(nets)) {
    const net = nets[name26];
    if (!net)
      continue;
    for (const netInfo of net) {
      if (netInfo.internal || netInfo.family !== "IPv4")
        continue;
      if (netInfo.address.startsWith("172."))
        continue;
      results.push(netInfo.address);
    }
  }
  return results;
}
