var PrCommand = cmd({
  command: "pr <number>",
  describe: "fetch and checkout a GitHub PR branch, then run opencode",
  builder: (yargs) => yargs.positional("number", {
    type: "number",
    describe: "PR number to checkout",
    demandOption: true
  }),
  async handler(args3) {
    await Instance.provide({
      directory: process.cwd(),
      async fn() {
        const project = Instance.project;
        if (project.vcs !== "git") {
          UI2.error("Could not find git repository. Please run this command from a git repository.");
          process.exit(1);
        }
        const prNumber = args3.number;
        const localBranchName = `pr/${prNumber}`;
        UI2.println(`Fetching and checking out PR #${prNumber}...`);
        const result6 = await Process.run(["gh", "pr", "checkout", `${prNumber}`, "--branch", localBranchName, "--force"], {
          nothrow: true
        });
        if (result6.code !== 0) {
          UI2.error(`Failed to checkout PR #${prNumber}. Make sure you have gh CLI installed and authenticated.`);
          process.exit(1);
        }
        const prInfoResult = await Process.text([
          "gh",
          "pr",
          "view",
          `${prNumber}`,
          "--json",
          "headRepository,headRepositoryOwner,isCrossRepository,headRefName,body"
        ], { nothrow: true });
        let sessionId;
        if (prInfoResult.code === 0) {
          const prInfoText = prInfoResult.text;
          if (prInfoText.trim()) {
            const prInfo = JSON.parse(prInfoText);
            if (prInfo && prInfo.isCrossRepository && prInfo.headRepository && prInfo.headRepositoryOwner) {
              const forkOwner = prInfo.headRepositoryOwner.login;
              const forkName = prInfo.headRepository.name;
              const remoteName = forkOwner;
              const remotes = (await git(["remote"], { cwd: Instance.worktree })).text().trim();
              if (!remotes.split(`
`).includes(remoteName)) {
                await git(["remote", "add", remoteName, `https://github.com/${forkOwner}/${forkName}.git`], {
                  cwd: Instance.worktree
                });
                UI2.println(`Added fork remote: ${remoteName}`);
              }
              const headRefName = prInfo.headRefName;
              await git(["branch", `--set-upstream-to=${remoteName}/${headRefName}`, localBranchName], {
                cwd: Instance.worktree
              });
            }
            if (prInfo && prInfo.body) {
              const sessionMatch = prInfo.body.match(/https:\/\/opncd\.ai\/s\/([a-zA-Z0-9_-]+)/);
              if (sessionMatch) {
                const sessionUrl = sessionMatch[0];
                UI2.println(`Found opencode session: ${sessionUrl}`);
                UI2.println(`Importing session...`);
                const importResult = await Process.text(["opencode", "import", sessionUrl], {
                  nothrow: true
                });
                if (importResult.code === 0) {
                  const importOutput = importResult.text.trim();
                  const sessionIdMatch = importOutput.match(/Imported session: ([a-zA-Z0-9_-]+)/);
                  if (sessionIdMatch) {
                    sessionId = sessionIdMatch[1];
                    UI2.println(`Session imported: ${sessionId}`);
                  }
                }
              }
            }
          }
        }
        UI2.println(`Successfully checked out PR #${prNumber} as branch '${localBranchName}'`);
        UI2.println();
        UI2.println("Starting opencode...");
        UI2.println();
        const opencodeArgs = sessionId ? ["-s", sessionId] : [];
        const opencodeProcess = Process.spawn(["opencode", ...opencodeArgs], {
          stdin: "inherit",
          stdout: "inherit",
          stderr: "inherit",
          cwd: process.cwd()
        });
        const code = await opencodeProcess.exited;
        if (code !== 0)
          throw new Error(`opencode exited with code ${code}`);
      }
    });
  }
});

