function pagerCmd() {
  const lessOptions = ["-R", "-S"];
  if (false) {}
  const lessOnPath = which("less");
  if (lessOnPath) {
    if (Filesystem.stat(lessOnPath)?.size)
      return [lessOnPath, ...lessOptions];
  }
  if (Flag.OPENCODE_GIT_BASH_PATH) {
    const less = path90.join(Flag.OPENCODE_GIT_BASH_PATH, "..", "..", "usr", "bin", "less.exe");
    if (Filesystem.stat(less)?.size)
      return [less, ...lessOptions];
  }
  const git2 = which("git");
  if (git2) {
    const less = path90.join(git2, "..", "..", "usr", "bin", "less.exe");
    if (Filesystem.stat(less)?.size)
      return [less, ...lessOptions];
  }
  return ["cmd", "/c", "more"];
}
